/* Walking monster easter egg. The wrapper carries the trip across the screen,
   the inner sprite only steps through the frames of assets/monster-walk.png —
   one row of 23 cells, 276 x 300 px each, a single gait cycle at 24 fps. The
   vertical bob is part of the artwork, so nothing bounces it here. */
.monster-walk {
  --frame-w: 184px;
  --frame-h: 200px;
  --sheet-w: calc(var(--frame-w) * 23);
  --cycle: 0.96s;
  --stride: 130px;
  --crossing: 16s;

  position: fixed;
  left: 0;
  bottom: 0;
  width: var(--frame-w);
  height: var(--frame-h);
  pointer-events: none;
  z-index: 10;
  animation: monster-cross var(--crossing) linear forwards;
}

.monster {
  position: absolute;
  inset: 0;
  background: url("assets/monster-walk.png") no-repeat;
  background-size: var(--sheet-w) var(--frame-h);
  transform: scaleX(-1);
  animation: monster-walk var(--cycle) steps(23) infinite;
}

@keyframes monster-walk {
  from { background-position: 0 0; }
  to { background-position: calc(-1 * var(--sheet-w)) 0; }
}

@keyframes monster-cross {
  from { transform: translateX(calc(-1 * var(--frame-w))); }
  to { transform: translateX(100vw); }
}

@media (prefers-reduced-motion: reduce) {
  .monster-walk {
    animation: none;
    transform: translateX(35vw);
  }

  .monster {
    animation: none;
  }
}

