const puppeteer = require('puppeteer-core');
const path = require('path');

const SITE = 'file:///<home>/source/repos/priv/monster-dev-testruns/2026-08-01-live/index.html';
const OUT = '<home>/AppData/Local/Temp/monster-check';
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

const state = () => {
  const el = document.querySelector('.monster-walk');
  const sprite = document.querySelector('.monster');
  const r = el.getBoundingClientRect();
  const cs = getComputedStyle(el);
  return {
    hidden: el.hidden,
    crossing: cs.getPropertyValue('--crossing').trim(),
    left: Math.round(r.left),
    right: Math.round(r.right),
    bottom: Math.round(r.bottom),
    viewportH: window.innerHeight,
    viewportW: window.innerWidth,
    spriteBgPos: getComputedStyle(sprite).backgroundPosition,
    spriteTransform: getComputedStyle(sprite).transform,
    zIndex: cs.zIndex,
    pointerEvents: cs.pointerEvents,
    animCount: el.getAnimations().length + sprite.getAnimations().length,
  };
};

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME,
    headless: 'shell',
    args: ['--allow-file-access-from-files', '--window-size=1280,800'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800 });

  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('requestfailed', (r) => errors.push('requestfailed: ' + r.url()));

  await page.goto(SITE, { waitUntil: 'networkidle0' });

  // 1. Nothing on load.
  console.log('on load          :', JSON.stringify(await page.evaluate(state)));
  await page.screenshot({ path: path.join(OUT, '1-onload.png') });

  // 2. A plain "a" must not trigger it.
  await page.keyboard.press('KeyA');
  await new Promise((r) => setTimeout(r, 300));
  console.log('plain "a"        :', JSON.stringify(await page.evaluate(state)));

  // 3. Alt+A.
  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  await new Promise((r) => setTimeout(r, 150));
  const started = await page.evaluate(state);
  console.log('after Alt+A      :', JSON.stringify(started));
  await page.screenshot({ path: path.join(OUT, '2-start.png') });

  // 4. Retrigger while walking must be ignored (position keeps advancing, no reset).
  await new Promise((r) => setTimeout(r, 1500));
  const midA = await page.evaluate(state);
  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  await new Promise((r) => setTimeout(r, 400));
  const midB = await page.evaluate(state);
  console.log('mid-walk         :', JSON.stringify(midA));
  console.log('after retrigger  :', JSON.stringify(midB));
  console.log('  -> advanced, not restarted:', midB.left > midA.left);
  console.log('  -> still one monster       :', (await page.$$('.monster-walk')).length === 1);
  await page.screenshot({ path: path.join(OUT, '3-mid.png') });

  // Sample sprite frames to prove it is stepping, not sliding.
  const frames = [];
  for (let i = 0; i < 6; i++) {
    frames.push((await page.evaluate(state)).spriteBgPos);
    await new Promise((r) => setTimeout(r, 130));
  }
  console.log('frame samples    :', frames.join(' | '));

  // Screenshot roughly mid-screen for a look at the actual pixels.
  await page.evaluate(() => {
    const el = document.querySelector('.monster-walk');
    el.getAnimations().forEach((a) => { a.currentTime = a.effect.getTiming().duration * 0.45; a.pause(); });
    document.querySelector('.monster').getAnimations().forEach((a) => { a.currentTime = 0; a.pause(); });
  });
  await new Promise((r) => setTimeout(r, 100));
  console.log('paused mid-screen:', JSON.stringify(await page.evaluate(state)));
  await page.screenshot({ path: path.join(OUT, '4-midscreen.png') });

  // 5. Runs to the end and cleans up.
  await page.evaluate(() => {
    document.querySelectorAll('.monster-walk, .monster').forEach((el) =>
      el.getAnimations().forEach((a) => { a.play(); a.currentTime = a.effect.getTiming().duration * 0.97; }));
  });
  await new Promise((r) => setTimeout(r, 1200));
  const ended = await page.evaluate(state);
  console.log('after walk ends  :', JSON.stringify(ended));

  // 6. Second walk works after the first finished.
  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  await new Promise((r) => setTimeout(r, 200));
  console.log('second Alt+A     :', JSON.stringify(await page.evaluate(state)));

  // 7. Narrow viewport: duration must scale with width, gait must not.
  const p2 = await browser.newPage();
  await p2.setViewport({ width: 420, height: 700 });
  await p2.goto(SITE, { waitUntil: 'networkidle0' });
  await p2.keyboard.down('Alt');
  await p2.keyboard.press('KeyA');
  await p2.keyboard.up('Alt');
  await new Promise((r) => setTimeout(r, 150));
  console.log('narrow 420px     :', JSON.stringify(await p2.evaluate(state)));
  await p2.screenshot({ path: path.join(OUT, '5-narrow.png') });
  await p2.close();

  // 8. prefers-reduced-motion.
  const p3 = await browser.newPage();
  await p3.setViewport({ width: 1280, height: 800 });
  await p3.emulateMediaFeatures([{ name: 'prefers-reduced-motion', value: 'reduce' }]);
  await p3.goto(SITE, { waitUntil: 'networkidle0' });
  await p3.keyboard.down('Alt');
  await p3.keyboard.press('KeyA');
  await p3.keyboard.up('Alt');
  await new Promise((r) => setTimeout(r, 300));
  console.log('reduced-motion   :', JSON.stringify(await p3.evaluate(state)));
  await p3.screenshot({ path: path.join(OUT, '6-reduced.png') });
  await new Promise((r) => setTimeout(r, 4200));
  console.log('reduced after 4s :', JSON.stringify(await p3.evaluate(state)));
  await p3.close();

  // 9. No layout damage: the page must not gain a horizontal scrollbar.
  console.log('h-overflow       :', await page.evaluate(() =>
    document.documentElement.scrollWidth > document.documentElement.clientWidth));

  console.log('errors           :', errors.length ? errors : 'none');
  await browser.close();
})();

