const puppeteer = require('puppeteer-core');

const SITE = 'file:///<home>/source/repos/priv/monster-dev-testruns/2026-08-01-live/index.html';
const OUT = '<home>/AppData/Local/Temp/monster-check';

(async () => {
  const browser = await puppeteer.launch({
    executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe',
    headless: 'shell',
    args: ['--allow-file-access-from-files', '--force-device-scale-factor=3'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 800, deviceScaleFactor: 3 });
  await page.goto(SITE, { waitUntil: 'networkidle0' });
  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');

  // Freeze mid-crossing on a chosen gait frame and zoom into the feet.
  for (const [name, frame] of [['contact', 0], ['midstep', 8], ['push-off', 15]]) {
    await page.evaluate((f) => {
      const el = document.querySelector('.monster-walk');
      const sprite = document.querySelector('.monster');
      el.getAnimations().forEach((a) => { a.pause(); a.currentTime = a.effect.getTiming().duration * 0.45; });
      sprite.getAnimations().forEach((a) => { a.pause(); a.currentTime = (a.effect.getTiming().duration / 23) * f; });
    }, frame);
    await new Promise((r) => setTimeout(r, 80));
    const box = await page.evaluate(() => {
      const r = document.querySelector('.monster-walk').getBoundingClientRect();
      return { x: r.left, y: r.top, width: r.width, height: r.height };
    });
    await page.screenshot({
      path: `${OUT}/zoom-${name}.png`,
      clip: { x: box.x - 10, y: box.y + box.height - 90, width: box.width + 20, height: 95 },
    });
    console.log(name, JSON.stringify(box));
  }
  await browser.close();
})();

